/// Secret-bearing reads retain ConsoleCrypt's Docker reveal step-up policy.
pub fn requires_reveal(operation: &str, args: &Value) -> bool {
    operation == "container_env"
        || matches!(operation, "inspect_container" | "inspect_image")
            && args
                .get("reveal_environment")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        || operation == "container_run_spec"
            && args
                .get("include_env")
                .and_then(Value::as_bool)
                .unwrap_or(false)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[tokio::test]
    async fn private_dispatcher_rejects_unknown_commands_and_never_echoes_input() {
        let error = dispatch(
            "arbitrary_shell",
            serde_json::json!({"password":"synthetic-secret"}),
        )
        .await
        .unwrap_err();
        assert_eq!(error.code, "unknown_operation");
        assert!(!error.to_string().contains("synthetic-secret"));
        let error = dispatch(
            "inspect_container",
            serde_json::json!({"container_id": {"secret":"synthetic-secret"}}),
        )
        .await
        .unwrap_err();
        assert_eq!(error.code, "invalid_input");
        assert!(!error.to_string().contains("synthetic-secret"));
    }
    #[test]
    fn only_explicit_secret_reads_require_reveal() {
        assert!(requires_reveal("container_env", &serde_json::json!({})));
        assert!(requires_reveal(
            "inspect_container",
            &serde_json::json!({"reveal_environment":true})
        ));
        assert!(!requires_reveal(
            "inspect_container",
            &serde_json::json!({"reveal_environment":false})
        ));
        assert!(requires_reveal(
            "container_run_spec",
            &serde_json::json!({"include_env":true})
        ));
        assert!(!requires_reveal("list_containers", &serde_json::json!({})));
    }
    #[test]
    fn unsigned_ids_round_trip_without_dart_number_precision_loss() {
        assert_eq!(
            encode(u64::MAX).unwrap(),
            Value::String(u64::MAX.to_string())
        );
        let mut value = serde_json::json!({"job":{"$u64":u64::MAX.to_string()}});
        restore_integers(&mut value).unwrap();
        assert_eq!(arg::<u64>(&value, "job").unwrap(), u64::MAX);
        assert!(restore_integers(&mut serde_json::json!({"$u64":"18446744073709551616"})).is_err());
    }
}
